const s = $('Settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r[`price_${s.fuel}`] != null);
if (!rows.length) return [{ json: { text: `No station selling ${s.fuel} within ${s.radiusKm} km.` } }];
const lines = rows.map((r, n) =>
  `${n + 1}. ${r[`price_${s.fuel}`].toFixed(3)} ${r.currency === 'EUR' ? '€' : r.currency} · ` +
  `${[r.brand, r.address, r.city].filter(Boolean).join(', ')} (${r.distanceKm} km)`);
return [{ json: { text: `⛽ Cheapest ${s.fuel} near you today\n${lines.join('\n')}\n\n${rows[0].attribution}` } }];
